begin;

-- Grade 6 Social Studies Term 3 mastery repair.
-- Adds explicit vocabulary, visual learning, differentiated practice and
-- assessment-with-guidance to every KICD sub-strand without changing authority rows.

with target as (
  select id from public.vibe_publications
  where id='66060000-0000-4000-8000-000000000003'::uuid
), packs(number,sentinel,additions,extra_words) as (
values
(1,'g6ss-t3-1-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-1-vocab','type','heading2','content','Words that unlock this chapter','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-1-vocab-p','type','paragraph','content','Government: the system used to make and carry out public decisions. Centralised: authority is concentrated around a strong centre. Chiefdom: a political community led by a chief. Council: a group that discusses and advises on decisions. Good governance: leadership guided by responsibility, fairness, consultation and service. Use each word in a sentence comparing Buganda and Nyamwezi rather than copying the definition.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-1-visual','type','callout','content','VISUAL LAB — Draw two governance flow diagrams. Buganda: Kabaka → council/chiefs → local administration. Nyamwezi: several chiefdoms, each with a chief supported by elders and community leaders. Add arrows showing both decisions moving outward and information moving inward. Alt-text goal: two contrasting diagrams showing a more centralised kingdom and several locally led chiefdoms.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-1-diff','type','callout','content','Learning support: use labelled role cards and sentence frames: Both systems…; Buganda differed because…; Nyamwezi differed because…. Extension: explain one possible strength and one possible limitation of centralised authority.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-1-assess','type','question','content','Mastery check: (1) Name the highest ruler in Buganda. (2) What was the Lukiiko? (3) Why is it inaccurate to describe all Nyamwezi as ruled by one king? (4) Give two similarities between the systems. (5) Explain one aspect of good governance shown through consultation or responsible leadership. Answer guide: Kabaka; an important council; Nyamwezi were organised in several chiefdoms; valid similarities include recognised leaders/advisers/order; final response must link a governance practice to fairness, consultation, accountability or responsible service.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),330),
(2,'g6ss-t3-2-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-2-vocab','type','heading2','content','Words that unlock regional cooperation','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-2-vocab-p','type','paragraph','content','Regional cooperation: countries working together on shared goals. Member state: a country belonging to an organisation. Integration: countries linking some activities, rules or markets more closely. Trade barrier: a rule or obstacle that makes cross-border trade harder. Harmonise: make rules or standards work together more consistently.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-2-visual','type','callout','content','VISUAL LAB — Create a teacher-vetted current map of EAC member states. Add icons for a road, border post, health cooperation, tourism and trade. Do not hard-code membership into a timeless illustration; label the visual with a verification date.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-2-diff','type','callout','content','Learning support: provide objective/benefit/challenge/solution cards for matching. Core: justify each match. Extension: choose one challenge and explain why a proposed regional solution may require compromise between national interests.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-2-assess','type','question','content','Mastery check: (1) What is regional cooperation? (2) Give two objectives of EAC cooperation. (3) Describe two benefits to member states. (4) Identify one challenge. (5) Propose a realistic solution and explain how it addresses the challenge. Answer guide: accept accurate explanations involving shared trade, movement, infrastructure, peace, development or coordinated services; challenge and solution must logically connect.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),320),
(3,'g6ss-t3-3-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-3-vocab','type','heading2','content','Words that unlock citizenship','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-3-vocab-p','type','paragraph','content','Citizen: a person who legally belongs to a country. Right: a protection or freedom recognised by law and society. Responsibility: a duty or expected action toward others and the community. Patriotism: constructive love and commitment to one’s country. Integrity: doing what is right and honest even when it is difficult.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-3-visual','type','callout','content','VISUAL LAB — Build a balance graphic. On the left place examples of rights; on the right place connected responsibilities. Draw links showing that responsible citizenship protects both individual dignity and the common good.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-3-diff','type','callout','content','Learning support: learners select from action cards before explaining orally. Core: explain the value behind each action. Extension: write a response to a dilemma where two citizens have competing interests and show how respectful citizenship can protect both.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-3-assess','type','question','content','Mastery check: (1) Distinguish a right from a responsibility. (2) Give two qualities of a good Kenyan citizen. (3) Show how integrity can be demonstrated at school. (4) Explain constructive patriotism. (5) Why is caring for public property a citizenship issue? Answer guide: responses should connect rights to protection/freedom, responsibilities to duties, values to observable actions and patriotism to service rather than slogans.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),315),
(4,'g6ss-t3-4-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-4-vocab','type','heading2','content','Words that unlock human rights','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-4-vocab-p','type','paragraph','content','Human rights: basic protections and freedoms connected to human dignity. Political rights: rights connected to participation and public life. Social rights: rights connected to well-being and participation in society. Economic rights: rights connected to livelihoods and economic life. Dignity: the worth that every person deserves to have respected.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-4-visual','type','callout','content','VISUAL LAB — Draw three overlapping circles: political, social and economic rights. Place examples in the circles and explain at least one overlap. The visual should teach that categories help organise rights but real life is interconnected.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-4-diff','type','callout','content','Learning support: classify pre-written safe examples with a partner. Core: explain how each right can be upheld. Extension: analyse a fictional situation where several rights are involved and propose a lawful, respectful response. No personal disclosure is required.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-4-assess','type','question','content','Mastery check: (1) Name the three KICD categories studied. (2) Give one example for each. (3) Describe two ways rights can be upheld. (4) Explain why respecting another person’s dignity matters. (5) In a fictional bullying case, identify a safe action that upholds rights. Answer guide: political/social/economic; examples must fit; safe actions can include seeking a trusted adult or appropriate school/public process.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),330),
(5,'g6ss-t3-5-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-5-vocab','type','heading2','content','Words that unlock peace-building','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-5-vocab-p','type','paragraph','content','Conflict: a disagreement or struggle between interests, needs or views. Dialogue: respectful conversation to understand and solve a problem. Negotiation: parties discuss possible agreement. Mediation: a neutral helper supports people to communicate and seek a solution. Social cohesion: people living and working together with trust, respect and belonging.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-5-visual','type','callout','content','VISUAL LAB — Create a conflict-resolution decision tree: Is anyone unsafe? → seek trusted adult/authority; if safe → listen and clarify → dialogue/negotiation → mediation if needed → agreement → review. Include a branch for rumours: verify before acting.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-5-diff','type','callout','content','Learning support: use illustrated scenario cards and a method word bank. Core: choose and justify a peaceful method. Extension: identify trigger, deeper cause and prevention strategy in the same case.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-5-assess','type','question','content','Mastery check: (1) Give two causes of conflict. (2) Distinguish dialogue from mediation. (3) Why should safety come first? (4) Give two ways a school can promote peace before conflict begins. (5) Explain why peaceful resolution is not the same as ignoring injustice. Answer guide: look for causes, accurate method distinctions, safeguarding, prevention and lawful/assertive action.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),325),
(6,'g6ss-t3-6-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-6-vocab','type','heading2','content','Words that unlock public finance','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-6-vocab-p','type','paragraph','content','Revenue: money received by government. Tax: a compulsory payment required by law. Expenditure: government spending. Budget: a plan showing expected resources and spending. Accountability: being responsible for decisions and able to explain how public resources were used.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-6-visual','type','callout','content','VISUAL LAB — Draw a public-finance cycle: households/businesses and other revenue sources → lawful government collection → budget decisions → public services → community outcomes → oversight/accountability. Use a fictional KSh 100 budget so learners can calculate proportions without relying on temporary national figures.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-6-diff','type','callout','content','Learning support: sort picture cards into revenue or expenditure. Core: explain the full money-to-service chain. Extension: compare two fictional budgets and defend which better responds to a stated community need while recognising trade-offs.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-6-assess','type','question','content','Mastery check: (1) Define revenue and expenditure. (2) Give three possible National Government revenue sources. (3) Give examples of national and county expenditure. (4) Why are taxes important? (5) Why does accountability matter after revenue is collected? Answer guide: distinguish inflow from spending, accept accurate sources/services, and connect tax to collective public services and accountability to lawful responsible use.','meta',jsonb_build_object('learning_layer','extend','assessment',true))
),335),
(7,'g6ss-t3-7-vocab',jsonb_build_array(
 jsonb_build_object('id','g6ss-t3-7-vocab','type','heading2','content','Words that unlock the Preamble','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-7-vocab-p','type','paragraph','content','Constitution: the supreme law that establishes the country’s legal and governance framework. Preamble: an opening statement introducing important values and purposes. Democracy: government in which people participate in choosing and holding leaders accountable through constitutional processes. Rule of law: everyone, including public officials, is subject to law. Social justice: fairness in society, especially in rights, opportunities and treatment.','meta',jsonb_build_object('learning_layer','comprehend')),
 jsonb_build_object('id','g6ss-t3-7-visual','type','callout','content','VISUAL LAB — Create a Preamble concept web from a central Constitution icon to learner-friendly ideas such as diversity, environment, human rights, equality, freedom, democracy, social justice, rule of law and the people’s sovereign authority. Exact quotations must be checked against an official Constitution.','meta',jsonb_build_object('learning_layer','apply','kind','visual_spec')),
 jsonb_build_object('id','g6ss-t3-7-diff','type','callout','content','Learning support: match key-word cards to plain-language meanings. Core: explain each in a civic situation. Extension: choose two Preamble ideas and show how they reinforce each other in a fair decision-making process.','meta',jsonb_build_object('learning_layer','apply','kind','differentiation')),
 jsonb_build_object('id','g6ss-t3-7-assess','type','question','content','Mastery check: (1) What is a Preamble? (2) Identify four key ideas from the official Preamble. (3) Explain rule of law in your own words. (4) Give one daily action that supports equality or dignity. (5) Why should exact constitutional wording be checked against an official source? Answer guide: assess understanding rather than memorised phrasing; rule of law must apply to both citizens and leaders; exact wording requires authoritative verification.','meta',jsonb_build_object('learning_layer','extend','assessment',true)),
 jsonb_build_object('id','g6ss-t3-term-mastery','type','activity','content','TERM 3 MASTERY CHALLENGE — Part A Political Systems: compare Buganda and Nyamwezi; solve one EAC cooperation problem; analyse a citizenship dilemma; classify and uphold rights. Part B Governance: resolve a fictional conflict peacefully; interpret a KSh 100 public budget; explain four Preamble ideas through everyday civic actions. Teacher marking: 4 marks per sub-strand = 28 marks. Award 1 for accurate concept, 1 for example/evidence, 1 for explanation/application and 1 for clear responsible judgement. Use weak domains to route remediation to the matching chapter rather than assigning a single overall revision task.','meta',jsonb_build_object('learning_layer','extend','assessment',true,'scope','term3'))
),430)
)
update public.vibe_chapters c
set blocks=c.blocks || p.additions,
    word_count=c.word_count+p.extra_words,
    reading_time_min=greatest(c.reading_time_min,ceil((c.word_count+p.extra_words)/180.0)::int),
    content_pack_version=2,
    updated_at=now()
from target t,packs p
where c.publication_id=t.id and c.number=p.number
and not exists(select 1 from jsonb_array_elements(c.blocks) b where b->>'id'=p.sentinel);

-- Fail closed on mastery pack completeness.
do $$
declare n int; assessment_n int; visual_n int; version_n int;
begin
 select count(*) into n from public.vibe_chapters where publication_id='66060000-0000-4000-8000-000000000003'::uuid;
 select count(distinct c.id) into assessment_n from public.vibe_chapters c cross join lateral jsonb_array_elements(c.blocks) b where c.publication_id='66060000-0000-4000-8000-000000000003'::uuid and coalesce((b->'meta'->>'assessment')::boolean,false)=true;
 select count(distinct c.id) into visual_n from public.vibe_chapters c cross join lateral jsonb_array_elements(c.blocks) b where c.publication_id='66060000-0000-4000-8000-000000000003'::uuid and b->'meta'->>'kind'='visual_spec';
 select count(*) into version_n from public.vibe_chapters where publication_id='66060000-0000-4000-8000-000000000003'::uuid and content_pack_version=2;
 if n<>7 or assessment_n<>7 or visual_n<>7 or version_n<>7 then
   raise exception 'GRADE6_SOCIAL_STUDIES_TERM3_MASTERY_GATE_FAILED chapters=% assessments=% visuals=% version2=%',n,assessment_n,visual_n,version_n;
 end if;
end $$;

commit;
